class SubscriptionStart
  def initialize
    raise RuntimeError, 'SubscriptionStart cannot be instantiated directly'
  end

  # Each enum variant is a nested class of the enum itself.
  class CURSOR
    
    attr_reader :cursor
    
    def initialize(cursor)
      
      @cursor = cursor
      
    end

    def to_s
      "SubscriptionStart::CURSOR(cursor=#{@cursor})"
    end

    def ==(other)
      if !other.cursor?
        return false
      end
      if @cursor != other.cursor
        return false
      end

      true
    end

    # For each variant, we have an `NAME?` method for easily checking
    # whether an instance is that variant.
    
    def cursor?
      instance_of? SubscriptionStart::CURSOR
    end
    
    def current_head?
      instance_of? SubscriptionStart::CURRENT_HEAD
    end
    
  end
  class CURRENT_HEAD
    
    attr_reader :current_head
    
    def initialize(current_head)
      
      @current_head = current_head
      
    end

    def to_s
      "SubscriptionStart::CURRENT_HEAD(current_head=#{@current_head})"
    end

    def ==(other)
      if !other.current_head?
        return false
      end
      if @current_head != other.current_head
        return false
      end

      true
    end

    # For each variant, we have an `NAME?` method for easily checking
    # whether an instance is that variant.
    
    def cursor?
      instance_of? SubscriptionStart::CURSOR
    end
    
    def current_head?
      instance_of? SubscriptionStart::CURRENT_HEAD
    end
    
  end
  
end


  
  
  

