  # Record type ActorObservation
class ActorObservation
  attr_reader :actor_id, :code_sha256, :home_region, :state, :subscriptions, :checkpoint_unix_millis, :checkpoint_epoch, :configuration_revision

  def initialize(actor_id:, code_sha256:, home_region:, state:, subscriptions:, checkpoint_unix_millis:, checkpoint_epoch:, configuration_revision:)
    @actor_id = actor_id
    @code_sha256 = code_sha256
    @home_region = home_region
    @state = state
    @subscriptions = subscriptions
    @checkpoint_unix_millis = checkpoint_unix_millis
    @checkpoint_epoch = checkpoint_epoch
    @configuration_revision = configuration_revision
  end

  def ==(other)
    if @actor_id != other.actor_id
      return false
    end
    if @code_sha256 != other.code_sha256
      return false
    end
    if @home_region != other.home_region
      return false
    end
    if @state != other.state
      return false
    end
    if @subscriptions != other.subscriptions
      return false
    end
    if @checkpoint_unix_millis != other.checkpoint_unix_millis
      return false
    end
    if @checkpoint_epoch != other.checkpoint_epoch
      return false
    end
    if @configuration_revision != other.configuration_revision
      return false
    end

    true
  end
end
  
  # Record type Header
class Header
  attr_reader :name, :value

  def initialize(name:, value:)
    @name = name
    @value = value
  end

  def ==(other)
    if @name != other.name
      return false
    end
    if @value != other.value
      return false
    end

    true
  end
end
  
