class InvokeActorResponse
  attr_reader :status, :body, :headers

  def initialize(status:, body:, headers:)
    @status = status
    @body = body
    @headers = headers
  end

  def ==(other)
    if @status != other.status
      return false
    end
    if @body != other.body
      return false
    end
    if @headers != other.headers
      return false
    end

    true
  end
end
  
