    @stream_path = stream_path
    @state = state
    @delivered_cursor = delivered_cursor
    @completed_cursor = completed_cursor
    @recoverable_cursor = recoverable_cursor
    @placement_anchor = placement_anchor
    @retry_count = retry_count
    @failure_code = failure_code
    @failed_cursor = failed_cursor
  end

  def ==(other)
    if @subscription_id != other.subscription_id
      return false
    end
    if @stream_path != other.stream_path
      return false
    end
    if @state != other.state
      return false
    end
    if @delivered_cursor != other.delivered_cursor
      return false
    end
    if @completed_cursor != other.completed_cursor
      return false
    end
    if @recoverable_cursor != other.recoverable_cursor
      return false
    end
    if @placement_anchor != other.placement_anchor
      return false
    end
    if @retry_count != other.retry_count
      return false
    end
    if @failure_code != other.failure_code
      return false
    end
    if @failed_cursor != other.failed_cursor
      return false
    end

    true
  end
end
  

  
  
